49	static __always_inline int icmp6_send_reply(struct __ctx_buff *ctx, int nh_off)
50	{
51		union macaddr smac, dmac = THIS_INTERFACE_MAC;
52		const int csum_off = nh_off + ICMP6_CSUM_OFFSET;
53		union v6addr sip, dip, router_ip = CONFIG(router_ipv6);
54		__be32 sum;
55	
56		if (ipv6_load_saddr(ctx, nh_off, &sip) < 0 ||
57		    ipv6_load_daddr(ctx, nh_off, &dip) < 0)
58			return DROP_INVALID;
59	
60		/* ctx->saddr = ctx->daddr */
61		if (ipv6_store_saddr(ctx, router_ip.addr, nh_off) < 0)
62			return DROP_WRITE_ERROR;
63		/* ctx->daddr = ctx->saddr */
64		if (ipv6_store_daddr(ctx, sip.addr, nh_off) < 0)
65			return DROP_WRITE_ERROR;
66	
67		/* fixup checksums */
68		sum = csum_diff(sip.addr, 16, router_ip.addr, 16, 0);
69		if (l4_csum_replace(ctx, csum_off, 0, sum, BPF_F_PSEUDO_HDR) < 0)
70			return DROP_CSUM_L4;
71	
72		sum = csum_diff(dip.addr, 16, sip.addr, 16, 0);
73		if (l4_csum_replace(ctx, csum_off, 0, sum, BPF_F_PSEUDO_HDR) < 0)
74			return DROP_CSUM_L4;
75	
76		/* dmac = smac, smac = dmac */
77		if (eth_load_saddr(ctx, smac.addr, 0) < 0)
78			return DROP_INVALID;
79	
80		if (eth_store_daddr(ctx, smac.addr, 0) < 0 ||
81		    eth_store_saddr(ctx, dmac.addr, 0) < 0)
82			return DROP_WRITE_ERROR;
83	
84		cilium_dbg_capture(ctx, DBG_CAPTURE_DELIVERY, ctx_get_ifindex(ctx));
85	
86		return redirect_self(ctx);
87	}
